import pytest
from retry import retry

def test_succeeds_after_failures():
    calls, sleeps = [], []
    @retry(retries=3, backoff=2.0, base_delay=0.5, exceptions=(IOError,), sleep=sleeps.append)
    def flaky():
        calls.append(1)
        if len(calls) < 3:
            raise IOError('nope')
        return 'ok'
    assert flaky() == 'ok'
    assert sleeps == [0.5, 1.0]

def test_gives_up():
    sleeps = []
    @retry(retries=2, backoff=3.0, base_delay=0.1, exceptions=(ValueError,), sleep=sleeps.append)
    def always_bad():
        raise ValueError('doom')
    with pytest.raises(ValueError):
        always_bad()
    assert sleeps == [0.1]

def test_wrong_exception_not_retried():
    sleeps = []
    @retry(retries=5, backoff=2.0, base_delay=1.0, exceptions=(KeyError,), sleep=sleeps.append)
    def wrong():
        raise RuntimeError('other')
    with pytest.raises(RuntimeError):
        wrong()
    assert sleeps == []

