def retry(retries, backoff, base_delay, exceptions, sleep):
    """Decorator that retries the wrapped function on matching exceptions.

    - ``retries`` is the *total* number of attempts (not extra retries).
    - Between attempts, sleeps ``base_delay * backoff ** n`` where n is the
      number of sleeps performed so far (no sleep after the final attempt).
    - Only exceptions listed in ``exceptions`` trigger a retry; anything else
      propagates immediately.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(retries):
                try:
                    return func(*args, **kwargs)
                except exceptions:
                    if attempt == retries - 1:
                        raise
                    sleep(base_delay * backoff ** attempt)
        return wrapper
    return decorator
